const app=useApp(),router=useRouter(),route=useRoute(),email=ref(''),password=ref(''),busy=ref(false),error=ref(''),form=ref(false)
async function login(){busy.value=true;error.value='';try{await app.login(email.value,password.value);await router.replace(String(route.query.redirect||'/'))}catch(e){error.value=app.errorMessage(e)}finally{busy.value=false}}
